// Normaliza entrada (data/payload ou direto)
const input = $input.first().json;
const data = input.data?.payload || input.data || input.payload || input;

return { json: data };

// ==========================================
// Gera Evento de Task
// ==========================================
// SPEC-EV-CO-009 a 013: Task requer ação do usuário
const crypto = require('crypto');

const input = $input.first().json;

// Gera ID único para o evento
const eventId = `task_${Date.now()}_${crypto.randomBytes(4).toString('hex')}`;

// Timestamp ISO 8601
const timestamp = new Date().toISOString();

// Prioridade padrão: normal
const priority = input.priority || 'normal';

// Target padrão: user
const target = input.target || 'user';

// Determina canal Redis baseado em target
let channel;
if (target === 'global') {
  channel = 'platform:events';
} else if (target === 'portal' && input.portalId) {
  channel = `platform:events:portal:${input.portalId}`;
} else {
  // user-specific
  const userId = Array.isArray(input.userId) ? input.userId[0] : input.userId;
  channel = `platform:events:user:${userId}`;
}

// Payload do evento (SPEC-EV-PL-017)
// Tasks incluem apenas metadados, dados completos via JQEL
const event = {
  type: 'task',
  id: eventId,
  userId: input.userId,
  category: input.category,
  priority: priority,
  timestamp: timestamp,
  target: target
};

if (target === 'portal' && input.portalId) {
  event.portalId = input.portalId;
}

// taskData é opcional (metadados adicionais)
if (input.taskData) {
  event.taskData = input.taskData;
}

return {
  json: {
    event,
    channel,
    userIds: Array.isArray(input.userId) ? input.userId : [input.userId]
  }
};

// ==========================================
// Publica no Redis Pub/Sub + Streams
// ==========================================
// SPEC-EV-N8-001: Backbone publica diretamente no Redis
// SPEC-EV-N8-002: Pub/Sub + Stream simultaneamente

// NOTA: Nodo Redis do n8n não suporta PUBLISH e XADD
// Por isso usamos ioredis diretamente

const Redis = require('ioredis');

const input = $input.first().json;
const { event, channel, userIds } = input;

// Conecta ao Redis usando mesmas credenciais do nodo Redis
const redis = new Redis({
  host: $env.REDIS_HOST || 'localhost',
  port: parseInt($env.REDIS_PORT || '6379'),
  password: $env.REDIS_PASSWORD || undefined,
  db: parseInt($env.REDIS_DB || '0'),
  lazyConnect: true,
  enableOfflineQueue: false,
  maxRetriesPerRequest: 3,
  retryStrategy: (times) => {
    if (times > 3) return null;
    return Math.min(times * 200, 1000);
  }
});

try {
  await redis.connect();

  const eventJson = JSON.stringify(event);

  // 1. Publica no Pub/Sub (entrega imediata)
  await redis.publish(channel, eventJson);

  // 2. Adiciona ao Stream de cada usuário (buffer 24h)
  const streamIds = [];
  for (const userId of userIds) {
    const streamKey = `events:${userId}`;

    // XADD com MAXLEN ~1000 (SPEC-EV-ST-006)
    const streamId = await redis.xadd(
      streamKey,
      'MAXLEN', '~', '1000',
      '*',
      'event', eventJson
    );

    streamIds.push(streamId);

    // Expira stream em 24h (SPEC-EV-ST-006)
    await redis.expire(streamKey, 86400);
  }

  await redis.quit();

  return {
    json: {
      code: 200,
      message: 'Task published',
      data: {
        eventId: event.id,
        channel: channel,
        streamIds: streamIds,
        userCount: userIds.length
      }
    }
  };

} catch (error) {
  // SPEC-EV-N8-008: Log erro mas não interrompe workflow
  console.error('Redis publish error:', error);

  try {
    await redis.quit();
  } catch (e) {
    // ignore
  }

  return {
    json: {
      code: 500,
      message: 'Failed to publish task',
      error: error.message
    }
  };
}
